# Define the logical operations
def not_(x):
    return not x

def and_(x, y):
    return x and y

def or_(x, y):
    return x or y

def implies(x, y):
    return not x or y

# Generate all possible truth values for A and B
truth_values = list(itertools.product([True, False], repeat=2))

# Function to evaluate expressions
def evaluate_expression(expr, A, B):
    if expr == "not_and":
        return not_(and_(A, B))
    elif expr == "or_not":
        return or_(not_(A), not_(B))
    elif expr == "not_or":
        return not_(or_(A, B))
    elif expr == "and_not":
        return and_(not_(A), not_(B))
    elif expr == "implies_1":
        return implies(A, B)
    elif expr == "implies_2":
        return implies(not_(B), not_(A))
    elif expr == "implies_3":
        return implies(not_(A), B)
    elif expr == "implies_4":
        return implies(A, B)
    elif expr == "implies_5":
        return implies(not_(A), B)
    elif expr == "not_implies":
        return not_(implies(A, B))
    elif expr == "and_not_B":
        return and_(A, not_(B))

# Evaluate all expressions for all combinations of A and B
expressions = {
    "not_and": [],
    "or_not": [],
    "not_or": [],
    "and_not": [],
    "implies_1": [],
    "implies_2": [],
    "implies_3": [],
    "implies_4": [],
    "not_implies": [],
    "and_not_B": []
}

for A, B in truth_values:
    for expr in expressions:
        expressions[expr].append(evaluate_expression(expr, A, B))

# Print the truth tables
for expr, results in expressions.items():
    print(f"Expression: {expr}, Truth Table: {results}")

# Compare the truth tables to find the non-equivalent expression
comparison_results = {}
for i, (expr, results) in enumerate(expressions.items()):
    comparison_results[expr] = []
    for j, (_, other_results) in enumerate(expressions.items()):
        if i != j:
            comparison_results[expr].append(results == other_results)

# Print the comparison results
for expr, comparisons in comparison_results.items():
    print(f"Expression: {expr}, Matches: {comparisons}")

